# tests/testthat/test-real-qvd.R
# ---------------------------------------------------------------------------
# Tests for reading real QlikSense-generated QVD files
# These tests use qcv_test_csv.qvd which was generated by QlikSense
# ---------------------------------------------------------------------------

# Skip tests if the real QVD file doesn't exist
test_that("read real QVD file from QlikSense", {
  qvd_path <- testthat::test_path("testdata", "qcv_test_csv.qvd")
  skip_if_not(file.exists(qvd_path), "Real QVD test file not found")

  result <- read_qvd(qvd_path, verbose = FALSE)

  # Check dimensions
  expect_equal(nrow(result), 10L)
  expect_equal(ncol(result), 5L)

  # Check column names
  expect_equal(names(result), c("Date_field", "number_field", "currency_field", "text_field", "datetime_field"))

  # Check column types
  expect_s3_class(result$Date_field, "Date")
  expect_true(is.numeric(result$number_field))
  expect_true(is.numeric(result$currency_field))
  expect_type(result$text_field, "character")
  expect_s3_class(result$datetime_field, "POSIXct")
})

test_that("read real QVD has correct date values", {
  qvd_path <- testthat::test_path("testdata", "qcv_test_csv.qvd")
  skip_if_not(file.exists(qvd_path), "Real QVD test file not found")

  result <- read_qvd(qvd_path, verbose = FALSE)

  # Check first date
  expect_equal(result$Date_field[1], as.Date("2026-04-01"))
  expect_equal(result$Date_field[2], as.Date("2026-04-02"))
  expect_equal(result$Date_field[10], as.Date("2018-12-10"))
})

test_that("read real QVD has correct numeric values", {
  qvd_path <- testthat::test_path("testdata", "qcv_test_csv.qvd")
  skip_if_not(file.exists(qvd_path), "Real QVD test file not found")

  result <- read_qvd(qvd_path, verbose = FALSE)

  # Check number_field values
  expect_equal(as.integer(result$number_field), 1:10)

  # Check currency_field values (the underlying numeric values, not display strings)
  expected_currency <- c(1, 10.05, 100.01, 1000, 2.34, 20.50, 200.10, 2000, 34, 45)
  expect_equal(result$currency_field, expected_currency, tolerance = 0.01)
})

test_that("read real QVD has correct text values", {
  qvd_path <- testthat::test_path("testdata", "qcv_test_csv.qvd")
  skip_if_not(file.exists(qvd_path), "Real QVD test file not found")

  result <- read_qvd(qvd_path, verbose = FALSE)

  expected_text <- c("apples", "bananas", "grapes", "pears", "oranges",
                     "lemons", "papaya", "kiwi", "coconuts", "strawberries")
  expect_equal(result$text_field, expected_text)
})

test_that("read real QVD has correct timestamp values", {
  qvd_path <- testthat::test_path("testdata", "qcv_test_csv.qvd")
  skip_if_not(file.exists(qvd_path), "Real QVD test file not found")

  result <- read_qvd(qvd_path, verbose = FALSE)

  # Check first timestamp
  expect_equal(result$datetime_field[1], as.POSIXct("2025-05-01 01:20:00", tz = "UTC"))
  expect_equal(result$datetime_field[2], as.POSIXct("2025-06-01 12:00:00", tz = "UTC"))
  expect_equal(result$datetime_field[10], as.POSIXct("2026-07-07 14:25:05", tz = "UTC"))
})
